window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8e2920c832298b2e"]={"versions": [{"id": "FIG-8e2920c832298b2e", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Kontroll- und Datenflusses auf der Empfängerseite (Rx) unter Verwendung eines COM-Callouts zur End-to-End-Absicherung (E2E Profile 01). Das Diagramm verortet sich im AUTOSAR Classic Platform Schichtenmodell zwischen Kommunikations-Hardwareabstraktion/Router (<code>PduR</code>), Kommunikationsmodul (<code>Com</code>), E2E Library (<code>E2E</code>), Laufzeitumgebung (<code>Rte</code>) und Software Component (<code>SWC</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» PduR</code>: PDU-Router, initiiert die Weiterleitung empfangener I-PDUs.\n</li><li><code>«module» Com</code>: AUTOSAR COM-Modul, steuert Signal-Deserialisierung und Callout-Aufrufe.\n</li><li><code>COM Callout IPDU_E2ECheck_21</code>: Anwenderspezifische Callout-Funktion zur Ausführung der E2E-Prüfung.\n</li><li><code>«module» E2E</code>: AUTOSAR E2E Library, stellt Prüfalgorithmen bereit.\n</li><li><code>«module» Rte</code>: AUTOSAR Runtime Environment, leitet Signale an SWC weiter.\n</li><li><code>SWC</code>: Software-Komponente als Senke der empfangenen Daten.\n</li></ul>\n<p class=\"fig-p\">Wichtige Schnittstellen und Datenstrukturen:</p>\n<ul class=\"fig-list\"><li><code>COM_RxIndication()</code>\n</li><li><code>IPDU_E2ECheck_21(RxPduId, IPduInfo)</code> mit Parametern für PDU-ID und PDU-Datenpointer.\n</li><li><code>E2E_P01Check(&amp;Settings, &amp;State, IPduInfo-&gt;SduDataPtr)</code>\n</li><li>Konfigurations- und Statusstrukturen: <code>Settings</code>, <code>State</code> (mit Membern <code>Status</code> und <code>NewDataAvailable</code>).\n</li><li>Rückgabewert <code>ret</code> (boolean).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzablauf auf der Empfängerseite:</p>\n<ol class=\"fig-list\"><li><code>PduR</code> meldet den Empfang einer I-PDU via <code>COM_RxIndication()</code> an <code>Com</code>.\n</li><li><code>Com</code> ruft den konfigurierten Callout <code>IPDU_E2ECheck_21(RxPduId, IPduInfo)</code> synchron auf.\n</li><li>Callout-Initialisierung / Vorbereitung:\n<ul class=\"fig-list\"><li>Einmalig beim Start (<code>[One time at startup]</code>): Fest verdrahtete Initialisierung der Konfigurations- und Zustandskonstrukte (<code>Settings</code>, <code>State</code>).\n</li><li>Vor jedem Check: Setzen von <code>State.NewDataAvailable = TRUE</code>.\n</li></ul>\n</li><li>Der Callout ruft <code>E2E_P01Check(&amp;Settings, &amp;State, IPduInfo-&gt;SduDataPtr)</code> im Modul <code>E2E</code> auf.\n</li><li><code>E2E</code> führt interne Prüfalgorithmen aus (<code>Execute check algorithms</code>) und gibt die aktualisierte Zustandsstruktur (<code>Updated State</code>) an den Callout zurück.\n</li><li>Der Callout evaluiert das Ergebnis: <code>ret = ((State.Status == E2E_P01STATUS_OK) || (State.Status == E2E_P01STATUS_OK))</code> (sic) und liefert <code>ret</code> an <code>Com</code> zurück.\n</li><li>Verzweigung in <code>Com</code>:\n<ul class=\"fig-list\"><li>Falls <code>ret == FALSE</code>: <code>[ret == FALSE]:exit processing of I-PDU</code> (Verarbeitung der I-PDU wird abgebrochen).\n</li><li>Falls gültig: <code>Com</code> erzeugt Signale aus der I-PDU 21 unter Berücksichtigung erforderlicher Konvertierungen (z. B. Endianness).\n</li></ul>\n</li><li><code>Com</code> übermittelt empfangene Signale (<code>Received signals</code>) an die <code>Rte</code>, welche diese als empfangene Datenelemente (<code>Received data elements</code>) an die Ziel-<code>SWC</code> weiterleitet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht ein Integrationsmuster für Legacy- bzw. Callout-basierte E2E-Prüfungen in AUTOSAR COM, bevor standardisierte E2E-Protection-Wrapper oder COM-basierte E2E-Transformer eingeführt wurden.</p>\n<p class=\"fig-p\">Besondere Implementierungsaspekte:</p>\n<ul class=\"fig-list\"><li>Die Auswertung im Callout enthält im Diagramm die redundante Bedingung <code>(State.Status == E2E_P01STATUS_OK) || (State.Status == E2E_P01STATUS_OK)</code>. In realen Implementierungen wird hier typischerweise zusätzlich <code>E2E_P01STATUS_OKSOMELOST</code> oder <code>E2E_P01STATUS_INITIAL</code> zugelassen.\n</li><li><code>State.NewDataAvailable</code> muss vor dem Prüfaufruf zwingend auf <code>TRUE</code> gesetzt werden, da die E2E-Bibliothek diesen Zustand für die Erkennung neuer Daten bzw. Datenverlust auswertet.\n</li><li>Bei fehlgeschlagener E2E-Prüfung (<code>ret == FALSE</code>) verwirft <code>Com</code> die PDU vollständig, sodass fehlerhafte Daten die Rte/SWC nicht erreichen.\n</li></ul>"}, {"id": "FIG-84677e3315aaa6d5", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Kontroll- und Datenflusses auf der Empfängerseite (Rx) unter Verwendung eines COM-Callouts zur End-to-End-Absicherung (E2E Profile 01). Das Diagramm verortet sich im AUTOSAR Classic Platform Schichtenmodell zwischen Kommunikations-Hardwareabstraktion/Router (<code>PduR</code>), Kommunikationsmodul (<code>Com</code>), E2E Library (<code>E2E</code>), Laufzeitumgebung (<code>Rte</code>) und Software Component (<code>SWC</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» PduR</code>: PDU-Router, initiiert die Weiterleitung empfangener I-PDUs.\n</li><li><code>«module» Com</code>: AUTOSAR COM-Modul, steuert Signal-Deserialisierung und Callout-Aufrufe.\n</li><li><code>COM Callout IPDU_E2ECheck_21</code>: Anwenderspezifische Callout-Funktion zur Ausführung der E2E-Prüfung.\n</li><li><code>«module» E2E</code>: AUTOSAR E2E Library, stellt Prüfalgorithmen bereit.\n</li><li><code>«module» Rte</code>: AUTOSAR Runtime Environment, leitet Signale an SWC weiter.\n</li><li><code>SWC</code>: Software-Komponente als Senke der empfangenen Daten.\n</li></ul>\n<p class=\"fig-p\">Wichtige Schnittstellen und Datenstrukturen:</p>\n<ul class=\"fig-list\"><li><code>COM_RxIndication()</code>\n</li><li><code>IPDU_E2ECheck_21(RxPduId, IPduInfo)</code> mit Parametern für PDU-ID und PDU-Datenpointer.\n</li><li><code>E2E_P01Check(&amp;Settings, &amp;State, IPduInfo-&gt;SduDataPtr)</code>\n</li><li>Konfigurations- und Statusstrukturen: <code>Settings</code>, <code>State</code> (mit Membern <code>Status</code> und <code>NewDataAvailable</code>).\n</li><li>Rückgabewert <code>ret</code> (boolean).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzablauf auf der Empfängerseite:</p>\n<ol class=\"fig-list\"><li><code>PduR</code> meldet den Empfang einer I-PDU via <code>COM_RxIndication()</code> an <code>Com</code>.\n</li><li><code>Com</code> ruft den konfigurierten Callout <code>IPDU_E2ECheck_21(RxPduId, IPduInfo)</code> synchron auf.\n</li><li>Callout-Initialisierung / Vorbereitung:\n<ul class=\"fig-list\"><li>Einmalig beim Start (<code>[One time at startup]</code>): Fest verdrahtete Initialisierung der Konfigurations- und Zustandskonstrukte (<code>Settings</code>, <code>State</code>).\n</li><li>Vor jedem Check: Setzen von <code>State.NewDataAvailable = TRUE</code>.\n</li></ul>\n</li><li>Der Callout ruft <code>E2E_P01Check(&amp;Settings, &amp;State, IPduInfo-&gt;SduDataPtr)</code> im Modul <code>E2E</code> auf.\n</li><li><code>E2E</code> führt interne Prüfalgorithmen aus (<code>Execute check algorithms</code>) und gibt die aktualisierte Zustandsstruktur (<code>Updated State</code>) an den Callout zurück.\n</li><li>Der Callout evaluiert das Ergebnis: <code>ret = ((State.Status == E2E_P01STATUS_OK) || (State.Status == E2E_P01STATUS_OK))</code> (sic) und liefert <code>ret</code> an <code>Com</code> zurück.\n</li><li>Verzweigung in <code>Com</code>:\n<ul class=\"fig-list\"><li>Falls <code>ret == FALSE</code>: <code>[ret == FALSE]:exit processing of I-PDU</code> (Verarbeitung der I-PDU wird abgebrochen).\n</li><li>Falls gültig: <code>Com</code> erzeugt Signale aus der I-PDU 21 unter Berücksichtigung erforderlicher Konvertierungen (z. B. Endianness).\n</li></ul>\n</li><li><code>Com</code> übermittelt empfangene Signale (<code>Received signals</code>) an die <code>Rte</code>, welche diese als empfangene Datenelemente (<code>Received data elements</code>) an die Ziel-<code>SWC</code> weiterleitet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht ein Integrationsmuster für Legacy- bzw. Callout-basierte E2E-Prüfungen in AUTOSAR COM, bevor standardisierte E2E-Protection-Wrapper oder COM-basierte E2E-Transformer eingeführt wurden.</p>\n<p class=\"fig-p\">Besondere Implementierungsaspekte:</p>\n<ul class=\"fig-list\"><li>Die Auswertung im Callout enthält im Diagramm die redundante Bedingung <code>(State.Status == E2E_P01STATUS_OK) || (State.Status == E2E_P01STATUS_OK)</code>. In realen Implementierungen wird hier typischerweise zusätzlich <code>E2E_P01STATUS_OKSOMELOST</code> oder <code>E2E_P01STATUS_INITIAL</code> zugelassen.\n</li><li><code>State.NewDataAvailable</code> muss vor dem Prüfaufruf zwingend auf <code>TRUE</code> gesetzt werden, da die E2E-Bibliothek diesen Zustand für die Erkennung neuer Daten bzw. Datenverlust auswertet.\n</li><li>Bei fehlgeschlagener E2E-Prüfung (<code>ret == FALSE</code>) verwirft <code>Com</code> die PDU vollständig, sodass fehlerhafte Daten die Rte/SWC nicht erreichen.\n</li></ul>"}], "trans": [{"from": "FIG-8e2920c832298b2e", "to": "FIG-84677e3315aaa6d5", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
